import sqlite3
import json
from itertools import combinations

# Load map data
conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cursor = conn.cursor()

cursor.execute("SELECT Width, Height FROM Map;")
width, height = cursor.fetchone()

cursor.execute("SELECT ID, TerrainType, IsImpassable FROM Plots;")
plots_data = cursor.fetchall()

cursor.execute("SELECT ID, FeatureType FROM PlotFeatures;")
features_data = cursor.fetchall()
features = {fid: ftype for fid, ftype in features_data}

conn.close()

# Build terrain map
terrain_map = {}
for plot_id, terrain, impassable in plots_data:
    x = plot_id % width
    y = plot_id // width
    terrain_map[(x, y)] = {
        'terrain': terrain,
        'impassable': impassable,
        'feature': features.get(plot_id, None)
    }

def get_neighbors(x, y):
    if y % 2 == 0:
        neighbors = [
            (x-1, y), (x+1, y),
            (x-1, y-1), (x, y-1),
            (x-1, y+1), (x, y+1)
        ]
    else:
        neighbors = [
            (x-1, y), (x+1, y),
            (x, y-1), (x+1, y-1),
            (x, y+1), (x+1, y+1)
        ]
    return [(nx, ny) for nx, ny in neighbors if (nx, ny) in terrain_map]

def is_valid_placement(x, y):
    if (x, y) not in terrain_map:
        return False
    tile = terrain_map[(x, y)]
    if 'OCEAN' in tile['terrain'] or 'COAST' in tile['terrain']:
        return False
    if 'MOUNTAIN' in tile['terrain']:
        return False
    if tile['impassable']:
        return False
    return True

def is_harbor_valid(x, y):
    if (x, y) not in terrain_map:
        return False
    tile = terrain_map[(x, y)]
    return 'COAST' in tile['terrain']

def calculate_bonus(district_type, x, y, placed_districts, city_center):
    neighbors = get_neighbors(x, y)
    bonus = 0

    if district_type == 'CAMPUS':
        for nx, ny in neighbors:
            ntile = terrain_map[(nx, ny)]
            if 'MOUNTAIN' in ntile['terrain']:
                bonus += 1
            if ntile['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
                bonus += 1
            if ntile['feature'] == 'FEATURE_REEF':
                bonus += 1
        jungle_count = sum(1 for nx, ny in neighbors if terrain_map[(nx, ny)]['feature'] in ['FEATURE_JUNGLE', 'FEATURE_MARSH'])
        bonus += jungle_count // 2

    elif district_type == 'HOLY_SITE':
        for nx, ny in neighbors:
            ntile = terrain_map[(nx, ny)]
            if 'MOUNTAIN' in ntile['terrain']:
                bonus += 1
        woods_count = sum(1 for nx, ny in neighbors if terrain_map[(nx, ny)]['feature'] == 'FEATURE_FOREST')
        bonus += woods_count // 2

    elif district_type == 'HARBOR':
        if city_center in neighbors:
            bonus += 2
        for nx, ny in neighbors:
            ntile = terrain_map[(nx, ny)]
            if ntile['feature'] == 'FEATURE_REEF':
                bonus += 1

    elif district_type == 'THEATER_SQUARE':
        district_count = sum(1 for nx, ny in neighbors if (nx, ny) in placed_districts and placed_districts[(nx, ny)] != 'THEATER_SQUARE')
        bonus += district_count // 2

    elif district_type == 'COMMERCIAL_HUB':
        harbor_count = sum(1 for nx, ny in neighbors if placed_districts.get((nx, ny)) == 'HARBOR')
        bonus += harbor_count * 2

    return bonus

# Try to find better combinations
valid_tiles = [(x, y) for x, y in terrain_map.keys() if is_valid_placement(x, y)]

print("Searching for better combinations...")

# Focus on city center at (20, 13) which seems good, but try others too
best_total = 9  # Current best
best_solution = None

for city_center in valid_tiles[:10]:  # Try first 10 valid tiles as city center
    cx, cy = city_center

    # Get potential district locations
    candidates = []
    for x, y in valid_tiles:
        if (x, y) != city_center:
            # Check if within reasonable range
            if abs(x - cx) <= 3 and abs(y - cy) <= 3:
                candidates.append((x, y))

    # Add harbor candidates
    harbor_candidates = []
    for x, y in terrain_map.keys():
        if is_harbor_valid(x, y) and (x, y) != city_center:
            if abs(x - cx) <= 3 and abs(y - cy) <= 3:
                if city_center in get_neighbors(x, y):
                    harbor_candidates.append((x, y))

    # Try different district type combinations
    district_types_to_try = [
        ['CAMPUS', 'HOLY_SITE', 'HARBOR', 'THEATER_SQUARE'],
        ['CAMPUS', 'HOLY_SITE', 'HARBOR', 'COMMERCIAL_HUB'],
        ['CAMPUS', 'HARBOR', 'THEATER_SQUARE', 'COMMERCIAL_HUB'],
        ['CAMPUS', 'HOLY_SITE', 'THEATER_SQUARE', 'COMMERCIAL_HUB'],
    ]

    for district_types in district_types_to_try:
        # For each district type, find best location
        best_placements = {}

        for dtype in district_types:
            best_loc = None
            best_score = -1

            locs_to_check = harbor_candidates if dtype == 'HARBOR' else candidates

            for loc in locs_to_check:
                if loc not in best_placements.values():
                    score = calculate_bonus(dtype, loc[0], loc[1], best_placements, city_center)
                    if score > best_score:
                        best_score = score
                        best_loc = loc

            if best_loc:
                best_placements[dtype] = best_loc

        # Calculate total with proper theater square bonus
        placed_districts = {loc: dtype for dtype, loc in best_placements.items()}
        total = 0
        details = []
        for dtype, loc in best_placements.items():
            bonus = calculate_bonus(dtype, loc[0], loc[1], placed_districts, city_center)
            total += bonus
            details.append((dtype, loc, bonus))

        if total > best_total:
            best_total = total
            best_solution = {
                'city_center': list(city_center),
                'districts': details
            }
            print(f"New best: {total} at city center {city_center}")
            for dtype, loc, bonus in details:
                print(f"  {dtype}: {loc} = {bonus}")

if best_solution:
    print(f"\nBest solution:")
    print(f"City center: {best_solution['city_center']}")
    print(f"Total: {best_total}")
    for dtype, loc, bonus in best_solution['districts']:
        print(f"  {dtype}: {loc} = {bonus}")
else:
    print("No better solution found, keeping current one.")

